#nullable enable // autogenerated

namespace MVZ2
{
    public static class StringHelper
    {
        public static string GetLastLines(this string text, int lineCount)
        {
            if (string.IsNullOrEmpty(text) || lineCount <= 0)
                return string.Empty;

            int end = text.Length;
            // 跳过末尾的换行符（不把结尾空行算作一行）
            while (end > 0 && (text[end - 1] == '\n' || text[end - 1] == '\r'))
                end--;

            int newlineCount = 0;
            int i = end - 1;
            for (; i >= 0; i--)
            {
                if (text[i] == '\n')
                {
                    if (++newlineCount == lineCount)
                    {
                        i++;   // 跳过这个 '\n'（若是 \r\n，'\r' 在其前一位，自然被跳过）
                        break;
                    }
                }
            }

            if (i < 0)                          // 行数不足 N 行
                return text.Substring(0, end);

            return text.Substring(i, end - i);  // 保留原文的 \r\n / \n
        }
    }
}
